/**
 * Generates docs/rules.md from knowledge/rules. Run `npm run docs:rules` after changing rules;
 * a test fails when the committed file is out of date.
 */
import { findItem } from '../checklist';
import { BEPO_BOVENGRONDS } from '../checklist/bepo-bovengronds';
import type { Rule } from '../domain/knowledge';
import { describeCondition } from './describe';

const cell = (s: string) => s.replace(/\|/g, '\\|').replace(/\n/g, ' ');

export function renderRulesDoc(rules: Rule[]): string {
  const lines = [
    '# Rules overview',
    '',
    '<!-- GENERATED by `npm run docs:rules` from knowledge/rules/*.json — do not edit by hand. -->',
    '',
    `${rules.length} rules. ✅ = verified by the inspector in the repo (\`verified_by_user\`).`,
    'Reviews done in the app ("Regels nakijken") are stored on the device until copied into the repo.',
    '',
  ];
  const sections = [...new Set(rules.map((r) => r.section))].sort(
    (a, b) => Number(a.slice(1)) - Number(b.slice(1)),
  );
  for (const section of sections) {
    const title = BEPO_BOVENGRONDS.sections.find((s) => s.code === section)?.title ?? '';
    lines.push(`## ${section} ${title}`, '');
    for (const r of rules.filter((x) => x.section === section)) {
      const items = r.items.map((id) => findItem(BEPO_BOVENGRONDS, id)?.label ?? id).join(', ');
      const validity =
        r.valid_from || r.valid_until
          ? `${r.valid_from ?? '…'} → ${r.valid_until ?? '…'}`
          : 'altijd';
      lines.push(
        `### ${r.verified_by_user ? '✅' : '⬜'} \`${r.id}\` — ${r.title_nl}`,
        '',
        '| | |',
        '|---|---|',
        `| Wanneer | ${cell(describeCondition(r.trigger))} |`,
        `| Resultaat | ${r.suggest_status ? `voorstel ${r.suggest_status}` : r.severity} |`,
        `| Tekst | ${r.standard_sentence ? `standaardzin \`${r.standard_sentence}\`` : cell(`“${r.text_nl ?? ''}”`)} |`,
        `| Artikel | ${cell(r.article)} |`,
        `| Items | ${cell(items)} |`,
        `| Geldig | ${validity} |`,
        `| Bron | ${cell(r.source)} |`,
      );
      if (r.note) lines.push(`| Noot | ${cell(r.note)} |`);
      lines.push('');
    }
  }
  return lines.join('\n');
}
